import { TriviaQuestion } from '../trivia-types'

export const GEOGRAPHY_QUESTIONS: TriviaQuestion[] = [
  { id: 'geo-1', category: 'geography', difficulty: 'easy', question: 'What is the capital of France?', answer: 'Paris', options: ['Lyon', 'Paris', 'Marseille', 'Nice'], explanation: 'Paris has been the capital of France since the late 10th century. It sits on the Seine River and is home to the Eiffel Tower, built for the 1889 World\'s Fair.' },
  { id: 'geo-2', category: 'geography', difficulty: 'easy', question: 'What is the largest continent by area?', answer: 'Asia', options: ['Africa', 'North America', 'Asia', 'Europe'], explanation: 'Asia covers about 44.6 million square kilometers, making it the largest continent by both area and population. It contains over 60% of the world\'s population.' },
  { id: 'geo-3', category: 'geography', difficulty: 'easy', question: 'What is the longest river in the world?', answer: 'Nile', options: ['Amazon', 'Mississippi', 'Nile', 'Yangtze'], explanation: 'The Nile stretches approximately 6,650 kilometers through northeastern Africa. It flows through 11 countries and empties into the Mediterranean Sea.' },
  { id: 'geo-4', category: 'geography', difficulty: 'easy', question: 'What ocean is the largest by area?', answer: 'Pacific Ocean', options: ['Atlantic Ocean', 'Indian Ocean', 'Pacific Ocean', 'Arctic Ocean'], explanation: 'The Pacific Ocean covers about 165 million square kilometers, more than all the land on Earth combined. It was named by explorer Ferdinand Magellan, who found its waters calm ("pacific" means peaceful).' },
  { id: 'geo-5', category: 'geography', difficulty: 'easy', question: 'What country has the most people?', answer: 'India', options: ['China', 'India', 'United States', 'Indonesia'], explanation: 'India surpassed China as the world\'s most populous country in 2023, with over 1.4 billion people. China held the top spot for centuries before that.' },
  { id: 'geo-6', category: 'geography', difficulty: 'easy', question: 'What is the smallest country in the world by area?', answer: 'Vatican City', options: ['Monaco', 'Vatican City', 'San Marino', 'Liechtenstein'], explanation: 'Vatican City covers just 0.44 square kilometers (about 110 acres) within the city of Rome. It became an independent state in 1929 through the Lateran Treaty with Italy.' },
  { id: 'geo-7', category: 'geography', difficulty: 'easy', question: 'What is the tallest mountain in the world?', answer: 'Mount Everest', options: ['K2', 'Mount Everest', 'Kangchenjunga', 'Mount Kilimanjaro'], explanation: 'Mount Everest stands at 8,849 meters (29,032 feet) above sea level on the border of Nepal and Tibet. It was first summited by Edmund Hillary and Tenzing Norgay in 1953.' },
  { id: 'geo-8', category: 'geography', difficulty: 'easy', question: 'What is the largest desert in the world?', answer: 'Antarctic Desert', options: ['Sahara', 'Antarctic Desert', 'Arabian Desert', 'Gobi Desert'], explanation: 'The Antarctic Desert covers about 14.2 million square kilometers, making it the largest desert by area. A desert is defined by low precipitation, not temperature — Antarctica receives very little snowfall.' },
  { id: 'geo-9', category: 'geography', difficulty: 'easy', question: 'How many continents are there?', answer: '7', options: ['5', '6', '7', '8'], explanation: 'The seven continents are Africa, Antarctica, Asia, Australia/Oceania, Europe, North America, and South America. Some models combine Europe and Asia into "Eurasia," but seven is the standard count in most English-speaking countries.' },
  { id: 'geo-10', category: 'geography', difficulty: 'easy', question: 'What country is known as the Land of the Rising Sun?', answer: 'Japan', options: ['China', 'South Korea', 'Japan', 'Thailand'], explanation: 'Japan\'s name in Japanese (Nihon or Nippon) literally means "origin of the sun." The name comes from Japan\'s position east of the Asian mainland, where the sun appears to rise.' },
  { id: 'geo-11', category: 'geography', difficulty: 'easy', question: 'What is the capital of Australia?', answer: 'Canberra', options: ['Sydney', 'Melbourne', 'Canberra', 'Brisbane'], explanation: 'Canberra was purpose-built as the capital starting in 1913 as a compromise between rivals Sydney and Melbourne. It is located in the Australian Capital Territory, roughly between the two larger cities.' },
  { id: 'geo-12', category: 'geography', difficulty: 'easy', question: 'What country\'s flag is this: 🇧🇷?', answer: 'Brazil', options: ['Portugal', 'Brazil', 'Colombia', 'Argentina'], explanation: 'Brazil\'s flag features a green background with a yellow diamond and a blue globe with white stars and a banner reading "Ordem e Progresso" (Order and Progress). The stars represent Brazil\'s states and the Federal District.' },
  { id: 'geo-13', category: 'geography', difficulty: 'easy', question: 'What is the largest country in the world by area?', answer: 'Russia', options: ['Canada', 'China', 'Russia', 'United States'], explanation: 'Russia spans about 17.1 million square kilometers, covering more than one-eighth of Earth\'s inhabited land area. It stretches across 11 time zones from Eastern Europe to the Pacific Ocean.' },
  { id: 'geo-14', category: 'geography', difficulty: 'easy', question: 'On which continent is Egypt located?', answer: 'Africa', options: ['Asia', 'Africa', 'Europe', 'Middle East'], explanation: 'Egypt is in northeastern Africa, though the Sinai Peninsula extends into Asia. The Suez Canal, completed in 1869, separates the African and Asian portions of Egypt.' },
  { id: 'geo-15', category: 'geography', difficulty: 'easy', question: 'What is the capital of Japan?', answer: 'Tokyo', options: ['Osaka', 'Kyoto', 'Tokyo', 'Yokohama'], explanation: 'Tokyo became the capital when Emperor Meiji moved from Kyoto in 1868. The Tokyo metropolitan area is the most populous in the world, with over 37 million people.' },
  { id: 'geo-16', category: 'geography', difficulty: 'easy', question: 'What body of water separates Europe from Africa at its narrowest point?', answer: 'Strait of Gibraltar', options: ['Suez Canal', 'Strait of Gibraltar', 'Mediterranean Sea', 'Red Sea'], explanation: 'The Strait of Gibraltar is only about 14 kilometers (8.7 miles) wide at its narrowest point. It connects the Atlantic Ocean to the Mediterranean Sea between Spain and Morocco.' },
  { id: 'geo-17', category: 'geography', difficulty: 'easy', question: 'What country\'s flag is this: 🇨🇦?', answer: 'Canada', options: ['Canada', 'Switzerland', 'Denmark', 'Peru'], explanation: 'Canada\'s flag features a red maple leaf on a white background flanked by red bars. It was officially adopted on February 15, 1965, replacing a flag that featured the British Union Jack.' },
  { id: 'geo-18', category: 'geography', difficulty: 'easy', question: 'What is the Great Barrier Reef located off the coast of?', answer: 'Australia', options: ['Indonesia', 'Philippines', 'Australia', 'New Zealand'], explanation: 'The Great Barrier Reef stretches over 2,300 kilometers along the northeast coast of Australia in the Coral Sea. It is the world\'s largest coral reef system, visible from space.' },
  { id: 'geo-19', category: 'geography', difficulty: 'easy', question: 'What is the capital of Italy?', answer: 'Rome', options: ['Milan', 'Rome', 'Venice', 'Florence'], explanation: 'Rome has been a center of power for over two millennia, from the Roman Republic to the modern Italian Republic. Vatican City, an independent country, is entirely surrounded by Rome.' },
  { id: 'geo-20', category: 'geography', difficulty: 'easy', question: 'What river runs through London?', answer: 'Thames', options: ['Seine', 'Danube', 'Thames', 'Rhine'], explanation: 'The River Thames flows 346 kilometers through southern England, passing through Oxford before reaching London. Its name is believed to come from a pre-Celtic word meaning "dark."' },
  { id: 'geo-21', category: 'geography', difficulty: 'easy', question: 'What country\'s flag is this: 🇯🇵?', answer: 'Japan', options: ['China', 'South Korea', 'Japan', 'Bangladesh'], explanation: 'Japan\'s flag is a white rectangle with a red circle (representing the sun) in the center. Known as the Hinomaru ("circle of the sun"), it has been used as a national symbol for centuries.' },
  { id: 'geo-22', category: 'geography', difficulty: 'easy', question: 'What is the deepest ocean on Earth?', answer: 'Pacific Ocean', options: ['Atlantic Ocean', 'Pacific Ocean', 'Indian Ocean', 'Southern Ocean'], explanation: 'The Pacific Ocean contains the Mariana Trench, the deepest point on Earth at about 10,984 meters (36,037 feet). The Challenger Deep within the trench was first reached by the bathyscaphe Trieste in 1960.' },
  { id: 'geo-23', category: 'geography', difficulty: 'easy', question: 'What is the capital of Germany?', answer: 'Berlin', options: ['Munich', 'Berlin', 'Frankfurt', 'Hamburg'], explanation: 'Berlin was divided into East and West during the Cold War from 1961 to 1989 by the Berlin Wall. After German reunification in 1990, Berlin was restored as the unified capital.' },
  { id: 'geo-24', category: 'geography', difficulty: 'easy', question: 'What U.S. state is the Grand Canyon located in?', answer: 'Arizona', options: ['Utah', 'Colorado', 'Arizona', 'Nevada'], explanation: 'The Grand Canyon in Arizona was carved by the Colorado River over millions of years and is up to 1,857 meters deep. It became a national park in 1919 and receives about 6 million visitors per year.' },
  { id: 'geo-25', category: 'geography', difficulty: 'easy', question: 'What country is home to the Amazon Rainforest\'s largest portion?', answer: 'Brazil', options: ['Peru', 'Colombia', 'Brazil', 'Venezuela'], explanation: 'About 60% of the Amazon Rainforest lies within Brazil. The Amazon is the world\'s largest tropical rainforest, covering approximately 5.5 million square kilometers across nine countries.' },
  { id: 'geo-26', category: 'geography', difficulty: 'easy', question: 'What is the capital of Canada?', answer: 'Ottawa', options: ['Toronto', 'Vancouver', 'Ottawa', 'Montreal'], explanation: 'Ottawa was chosen as Canada\'s capital in 1857 by Queen Victoria, partly because of its location on the border of Ontario and Quebec. Toronto and Montreal are larger cities, but Ottawa serves as the political center.' },
  { id: 'geo-27', category: 'geography', difficulty: 'easy', question: 'What is the largest lake in Africa?', answer: 'Lake Victoria', options: ['Lake Tanganyika', 'Lake Victoria', 'Lake Malawi', 'Lake Chad'], explanation: 'Lake Victoria covers about 68,800 square kilometers, making it Africa\'s largest lake and the world\'s largest tropical lake. It is shared by Tanzania, Uganda, and Kenya and is the primary source of the Nile River.' },
  { id: 'geo-28', category: 'geography', difficulty: 'easy', question: 'What country\'s flag is this: 🇲🇽?', answer: 'Mexico', options: ['Italy', 'Mexico', 'Ireland', 'Hungary'], explanation: 'Mexico\'s flag has green, white, and red vertical stripes with the national coat of arms (an eagle perched on a cactus eating a snake) in the center. Italy\'s flag is similar but lacks the coat of arms and uses slightly different shades.' },
  { id: 'geo-29', category: 'geography', difficulty: 'easy', question: 'What mountain range separates Europe from Asia?', answer: 'Ural Mountains', options: ['Alps', 'Himalayas', 'Ural Mountains', 'Caucasus Mountains'], explanation: 'The Ural Mountains stretch about 2,500 kilometers from the Arctic Ocean to the Ural River in Kazakhstan. They are one of the oldest mountain ranges in the world, formed 250-300 million years ago.' },
  { id: 'geo-30', category: 'geography', difficulty: 'easy', question: 'What is the capital of Spain?', answer: 'Madrid', options: ['Barcelona', 'Madrid', 'Seville', 'Valencia'], explanation: 'Madrid is located in the center of the Iberian Peninsula and is one of the highest capital cities in Europe at 650 meters elevation. It is home to the Prado Museum and the Royal Palace.' },
  { id: 'geo-31', category: 'geography', difficulty: 'easy', question: 'What is the largest island in the world?', answer: 'Greenland', options: ['Borneo', 'Madagascar', 'Greenland', 'New Guinea'], explanation: 'Greenland covers about 2.17 million square kilometers, making it the world\'s largest island (Australia is considered a continent). Despite its name, about 80% of Greenland is covered by an ice sheet.' },
  { id: 'geo-32', category: 'geography', difficulty: 'easy', question: 'What two countries share the longest international border?', answer: 'United States and Canada', options: ['Russia and China', 'United States and Canada', 'Argentina and Chile', 'Russia and Kazakhstan'], explanation: 'The U.S.-Canada border stretches 8,891 kilometers (5,525 miles), including the Alaska-Canada border. It is often called the longest undefended border in the world.' },
  { id: 'geo-33', category: 'geography', difficulty: 'easy', question: 'What is the capital of Egypt?', answer: 'Cairo', options: ['Alexandria', 'Cairo', 'Luxor', 'Giza'], explanation: 'Cairo is the largest city in Africa and the Arab world, with a metropolitan population of over 20 million. The nearby Giza Plateau is home to the Great Pyramids and the Sphinx.' },
  { id: 'geo-34', category: 'geography', difficulty: 'easy', question: 'What country\'s flag is this: 🇮🇳?', answer: 'India', options: ['India', 'Ireland', 'Ivory Coast', 'Niger'], explanation: 'India\'s flag has three horizontal stripes of saffron, white, and green, with a navy blue Ashoka Chakra (24-spoke wheel) in the center. The wheel represents the eternal cycle of law and dharma.' },
  { id: 'geo-35', category: 'geography', difficulty: 'easy', question: 'What is the driest continent on Earth?', answer: 'Antarctica', options: ['Africa', 'Australia', 'Antarctica', 'South America'], explanation: 'Antarctica receives an average of only about 166 millimeters of precipitation per year, making it technically a desert. Its interior is even drier, receiving less than 50 millimeters annually.' },
  { id: 'geo-36', category: 'geography', difficulty: 'medium', question: 'What is the capital of Turkey?', answer: 'Ankara', options: ['Istanbul', 'Ankara', 'Izmir', 'Antalya'], explanation: 'Ankara replaced Istanbul as Turkey\'s capital in 1923 when Mustafa Kemal Ataturk founded the Republic of Turkey. Istanbul remains the country\'s largest city and economic center.' },
  { id: 'geo-37', category: 'geography', difficulty: 'medium', question: 'What is the longest river in Europe?', answer: 'Volga', options: ['Danube', 'Rhine', 'Volga', 'Thames'], explanation: 'The Volga River flows about 3,530 kilometers entirely within Russia, emptying into the Caspian Sea. It drains most of western Russia and is sometimes called "Mother Volga" by Russians.' },
  { id: 'geo-38', category: 'geography', difficulty: 'medium', question: 'What country has the most natural lakes?', answer: 'Canada', options: ['Finland', 'Canada', 'Sweden', 'Russia'], explanation: 'Canada contains an estimated 879,800 lakes covering about 9% of its total area. This includes over half of the world\'s natural lakes, largely a result of glacial activity during the last Ice Age.' },
  { id: 'geo-39', category: 'geography', difficulty: 'medium', question: 'What is the smallest U.S. state by area?', answer: 'Rhode Island', options: ['Delaware', 'Connecticut', 'Rhode Island', 'New Jersey'], explanation: 'Rhode Island covers only about 4,001 square kilometers (1,545 square miles). Its official name was "State of Rhode Island and Providence Plantations" until 2020, when voters approved shortening it to just "State of Rhode Island."' },
  { id: 'geo-40', category: 'geography', difficulty: 'medium', question: 'What country\'s flag is this: 🇹🇷?', answer: 'Turkey', options: ['Tunisia', 'Turkey', 'Pakistan', 'Algeria'], explanation: 'Turkey\'s flag features a white crescent moon and star on a red background. The design dates back to the Ottoman Empire, and the flag is commonly known as "al bayrak" (the red flag) in Turkish.' },
  { id: 'geo-41', category: 'geography', difficulty: 'medium', question: 'What African country was formerly known as Abyssinia?', answer: 'Ethiopia', options: ['Eritrea', 'Somalia', 'Ethiopia', 'Sudan'], explanation: 'Ethiopia was known as Abyssinia for centuries and is one of the oldest nations in the world. It is the only African country that was never colonized, though Italy briefly occupied it from 1936 to 1941.' },
  { id: 'geo-42', category: 'geography', difficulty: 'medium', question: 'What is the deepest lake in the world?', answer: 'Lake Baikal', options: ['Lake Superior', 'Lake Baikal', 'Caspian Sea', 'Lake Tanganyika'], explanation: 'Lake Baikal in Siberia, Russia reaches a maximum depth of 1,642 meters (5,387 feet). It contains about 20% of the world\'s unfrozen fresh surface water and is estimated to be 25 million years old.' },
  { id: 'geo-43', category: 'geography', difficulty: 'medium', question: 'What is the capital of Brazil?', answer: 'Brasilia', options: ['Rio de Janeiro', 'Sao Paulo', 'Brasilia', 'Salvador'], explanation: 'Brasilia was purpose-built as Brazil\'s new capital and inaugurated in 1960, replacing Rio de Janeiro. Designed by Oscar Niemeyer and Lucio Costa, its layout from the air resembles an airplane.' },
  { id: 'geo-44', category: 'geography', difficulty: 'medium', question: 'What is the most spoken native language in the world?', answer: 'Mandarin Chinese', options: ['English', 'Spanish', 'Mandarin Chinese', 'Hindi'], explanation: 'Mandarin Chinese has about 920 million native speakers, making it the most spoken first language. English has the most total speakers (native plus second language) at over 1.4 billion.' },
  { id: 'geo-45', category: 'geography', difficulty: 'medium', question: 'What country is home to Machu Picchu?', answer: 'Peru', options: ['Bolivia', 'Ecuador', 'Peru', 'Colombia'], explanation: 'Machu Picchu sits at about 2,430 meters elevation in the Andes of Peru. It was built by the Inca emperor Pachacuti in the 15th century and was unknown to the outside world until Hiram Bingham\'s expedition in 1911.' },
  { id: 'geo-46', category: 'geography', difficulty: 'medium', question: 'What strait separates Asia from North America?', answer: 'Bering Strait', options: ['Strait of Hormuz', 'Bering Strait', 'Strait of Malacca', 'Strait of Magellan'], explanation: 'The Bering Strait is about 82 kilometers (51 miles) wide, separating Russia from Alaska. During the last Ice Age, lower sea levels exposed a land bridge here that allowed humans to migrate from Asia to the Americas.' },
  { id: 'geo-47', category: 'geography', difficulty: 'medium', question: 'What country has the most time zones?', answer: 'France', options: ['Russia', 'United States', 'France', 'United Kingdom'], explanation: 'France spans 12 time zones due to its overseas territories scattered across the globe, including French Polynesia, New Caledonia, and Reunion. Russia has 11 contiguous time zones, the most for any country without overseas territories.' },
  { id: 'geo-48', category: 'geography', difficulty: 'medium', question: 'What is the capital of South Korea?', answer: 'Seoul', options: ['Busan', 'Seoul', 'Incheon', 'Pyongyang'], explanation: 'Seoul has been the capital of Korea for over 600 years, since the Joseon Dynasty in 1394. Its metropolitan area is home to about 25 million people, roughly half of South Korea\'s entire population.' },
  { id: 'geo-49', category: 'geography', difficulty: 'medium', question: 'What country\'s flag is this: 🇿🇦?', answer: 'South Africa', options: ['South Africa', 'Kenya', 'Ghana', 'Tanzania'], explanation: 'South Africa\'s flag was adopted in 1994 when apartheid ended and features six colors: black, gold, green, white, red, and blue in a Y-shape design. It is one of the most colorful national flags in the world.' },
  { id: 'geo-50', category: 'geography', difficulty: 'medium', question: 'What is the highest waterfall in the world?', answer: 'Angel Falls', options: ['Niagara Falls', 'Victoria Falls', 'Angel Falls', 'Iguazu Falls'], explanation: 'Angel Falls in Venezuela drops 979 meters (3,212 feet) from the top of Auyantepui mountain. It was named after Jimmy Angel, an American aviator who flew over it in 1933.' },
  { id: 'geo-51', category: 'geography', difficulty: 'medium', question: 'What European country has the most UNESCO World Heritage Sites?', answer: 'Italy', options: ['Spain', 'France', 'Italy', 'Germany'], explanation: 'Italy has the most UNESCO World Heritage Sites of any country, with over 55 sites. These include the Colosseum, the historic center of Florence, Venice, and the archaeological sites of Pompeii.' },
  { id: 'geo-52', category: 'geography', difficulty: 'medium', question: 'What is the only country that borders both the Atlantic and Indian Oceans?', answer: 'South Africa', options: ['Mozambique', 'South Africa', 'Madagascar', 'Tanzania'], explanation: 'South Africa sits at the southern tip of Africa where the Atlantic and Indian Oceans meet near the Cape of Good Hope. Cape Agulhas, not the Cape of Good Hope, is actually the southernmost point of Africa.' },
  { id: 'geo-53', category: 'geography', difficulty: 'medium', question: 'What river flows through the most capital cities?', answer: 'Danube', options: ['Rhine', 'Danube', 'Nile', 'Mekong'], explanation: 'The Danube River flows through four capital cities: Vienna (Austria), Bratislava (Slovakia), Budapest (Hungary), and Belgrade (Serbia). It is Europe\'s second-longest river after the Volga.' },
  { id: 'geo-54', category: 'geography', difficulty: 'medium', question: 'What country is the world\'s largest producer of coffee?', answer: 'Brazil', options: ['Colombia', 'Vietnam', 'Brazil', 'Ethiopia'], explanation: 'Brazil produces about one-third of the world\'s coffee, a position it has held for over 150 years. Coffee was introduced to Brazil in the 1700s and became the backbone of its economy in the 19th century.' },
  { id: 'geo-55', category: 'geography', difficulty: 'medium', question: 'What is the capital of New Zealand?', answer: 'Wellington', options: ['Auckland', 'Wellington', 'Christchurch', 'Queenstown'], explanation: 'Wellington became New Zealand\'s capital in 1865, replacing Auckland due to its more central location. It is the world\'s southernmost capital of a sovereign state.' },
  { id: 'geo-56', category: 'geography', difficulty: 'medium', question: 'What is the largest country in Africa by area?', answer: 'Algeria', options: ['Democratic Republic of Congo', 'Sudan', 'Algeria', 'Libya'], explanation: 'Algeria covers about 2.38 million square kilometers, making it the largest country in Africa. It became the largest after South Sudan split from Sudan in 2011, reducing Sudan\'s total area.' },
  { id: 'geo-57', category: 'geography', difficulty: 'medium', question: 'What country\'s flag is this: 🇰🇷?', answer: 'South Korea', options: ['North Korea', 'South Korea', 'Japan', 'Taiwan'], explanation: 'South Korea\'s flag (Taegukgi) features a red and blue yin-yang symbol in the center with four black trigrams from the I Ching in the corners. The white background symbolizes peace and purity.' },
  { id: 'geo-58', category: 'geography', difficulty: 'medium', question: 'What is the Ring of Fire?', answer: 'A zone of volcanic and seismic activity around the Pacific Ocean', options: ['A volcanic region in Iceland', 'A zone of volcanic and seismic activity around the Pacific Ocean', 'A chain of volcanoes in Hawaii', 'A fault line running through California'], explanation: 'The Ring of Fire stretches about 40,000 kilometers around the edges of the Pacific Ocean. It contains about 75% of the world\'s active volcanoes and is where about 90% of the world\'s earthquakes occur.' },
  { id: 'geo-59', category: 'geography', difficulty: 'medium', question: 'What country is known as the "Pearl of the Indian Ocean"?', answer: 'Sri Lanka', options: ['Maldives', 'Sri Lanka', 'Mauritius', 'Madagascar'], explanation: 'Sri Lanka earned this nickname due to its natural beauty, strategic location in the Indian Ocean, and teardrop shape. The island nation was known as Ceylon until it changed its name in 1972.' },
  { id: 'geo-60', category: 'geography', difficulty: 'medium', question: 'What is the capital of Nigeria?', answer: 'Abuja', options: ['Lagos', 'Abuja', 'Kano', 'Port Harcourt'], explanation: 'Abuja replaced Lagos as Nigeria\'s capital in 1991. Like Brasilia and Canberra, it was a planned city built specifically to serve as the capital, chosen for its central location within the country.' },
  { id: 'geo-61', category: 'geography', difficulty: 'medium', question: 'What country has the longest coastline in the world?', answer: 'Canada', options: ['Indonesia', 'Australia', 'Canada', 'Russia'], explanation: 'Canada\'s coastline stretches about 202,080 kilometers, touching the Atlantic, Pacific, and Arctic Oceans. This extraordinary length is partly due to the country\'s many islands and fjords in the Arctic archipelago.' },
  { id: 'geo-62', category: 'geography', difficulty: 'medium', question: 'What mountain range contains Mount Everest?', answer: 'Himalayas', options: ['Karakoram', 'Himalayas', 'Hindu Kush', 'Kunlun'], explanation: 'The Himalayas stretch about 2,400 kilometers across five countries: India, Nepal, Bhutan, China, and Pakistan. The range contains 10 of the world\'s 14 peaks above 8,000 meters, with the other four in the neighboring Karakoram range.' },
  { id: 'geo-63', category: 'geography', difficulty: 'medium', question: 'What is the currency of Japan?', answer: 'Yen', options: ['Won', 'Yuan', 'Yen', 'Ringgit'], explanation: 'The Japanese yen was established in 1871 as part of the Meiji government\'s modernization. The word "yen" means "round object" in Japanese, referring to the shape of coins.' },
  { id: 'geo-64', category: 'geography', difficulty: 'medium', question: 'What country\'s flag is this: 🇸🇪?', answer: 'Sweden', options: ['Finland', 'Norway', 'Sweden', 'Denmark'], explanation: 'Sweden\'s flag features a yellow (gold) Nordic cross on a blue background. The Nordic cross design is shared by all Scandinavian countries, with Denmark\'s Dannebrog being the oldest continuously used national flag in the world.' },
  { id: 'geo-65', category: 'geography', difficulty: 'medium', question: 'What is the largest freshwater lake in South America?', answer: 'Lake Titicaca', options: ['Lake Maracaibo', 'Lake Titicaca', 'Lake Poopo', 'Lagoa dos Patos'], explanation: 'Lake Titicaca sits at 3,812 meters elevation on the border of Peru and Bolivia, making it the highest navigable lake in the world. It covers about 8,372 square kilometers.' },
  { id: 'geo-66', category: 'geography', difficulty: 'medium', question: 'What country is the Serengeti located in?', answer: 'Tanzania', options: ['Kenya', 'Tanzania', 'South Africa', 'Uganda'], explanation: 'The Serengeti ecosystem spans about 30,000 square kilometers in northern Tanzania and extends into Kenya as the Maasai Mara. It is famous for the annual migration of over 1.5 million wildebeest.' },
  { id: 'geo-67', category: 'geography', difficulty: 'medium', question: 'What is the national language of Brazil?', answer: 'Portuguese', options: ['Spanish', 'Portuguese', 'Brazilian', 'English'], explanation: 'Brazil is the only Portuguese-speaking country in the Americas, a legacy of Portuguese colonization beginning in 1500. Brazil has more Portuguese speakers than Portugal itself — over 210 million compared to about 10 million.' },
  { id: 'geo-68', category: 'geography', difficulty: 'medium', question: 'What major European city straddles two continents?', answer: 'Istanbul', options: ['Moscow', 'Istanbul', 'Athens', 'Tbilisi'], explanation: 'Istanbul spans both Europe and Asia, divided by the Bosphorus strait. While Istanbul is not Turkey\'s current capital (that is Ankara), it served as the capital of the Byzantine and Ottoman Empires and remains the country\'s largest city.' },
  { id: 'geo-69', category: 'geography', difficulty: 'medium', question: 'What is the largest bay in the world by area?', answer: 'Bay of Bengal', options: ['Hudson Bay', 'Bay of Bengal', 'Bay of Biscay', 'Gulf of Mexico'], explanation: 'The Bay of Bengal covers about 2.17 million square kilometers in the northeastern Indian Ocean. It is bordered by India, Bangladesh, Myanmar, and Sri Lanka, and is known for frequent tropical cyclones.' },
  { id: 'geo-70', category: 'geography', difficulty: 'medium', question: 'What country\'s flag is this: 🇳🇴?', answer: 'Norway', options: ['Iceland', 'Norway', 'Denmark', 'Finland'], explanation: 'Norway\'s flag features a blue cross outlined in white on a red background. It was designed in 1821 by Fredrik Meltzer and combines the red of Denmark\'s flag with the blue cross of Sweden\'s.' },
  { id: 'geo-71', category: 'geography', difficulty: 'medium', question: 'What is the largest hot desert in the world?', answer: 'Sahara Desert', options: ['Arabian Desert', 'Sahara Desert', 'Kalahari Desert', 'Great Victoria Desert'], explanation: 'The Sahara covers about 9.2 million square kilometers across northern Africa, roughly the size of the United States. While the Antarctic and Arctic deserts are larger overall, the Sahara is the largest hot desert.' },
  { id: 'geo-72', category: 'geography', difficulty: 'medium', question: 'What city is known as the "City of Canals"?', answer: 'Venice', options: ['Amsterdam', 'Venice', 'Bangkok', 'Bruges'], explanation: 'Venice, Italy is built on 118 small islands connected by over 400 bridges across its famous canals. The city has no roads — transportation is by boat, including the iconic gondolas and water taxis.' },
  { id: 'geo-73', category: 'geography', difficulty: 'medium', question: 'What is the capital of Thailand?', answer: 'Bangkok', options: ['Chiang Mai', 'Phuket', 'Bangkok', 'Pattaya'], explanation: 'Bangkok\'s ceremonial full name in Thai is the longest city name in the world, with 168 characters. The city is home to over 10 million people and serves as Thailand\'s political, economic, and cultural center.' },
  { id: 'geo-74', category: 'geography', difficulty: 'medium', question: 'What is the second-largest country in South America by area?', answer: 'Argentina', options: ['Colombia', 'Peru', 'Argentina', 'Chile'], explanation: 'Argentina covers about 2.78 million square kilometers, second only to Brazil in South America. It stretches from the subtropical north to the subantarctic south, spanning over 3,400 kilometers in length.' },
  { id: 'geo-75', category: 'geography', difficulty: 'medium', question: 'What is the official currency of the United Kingdom?', answer: 'Pound sterling', options: ['Euro', 'Pound sterling', 'Dollar', 'Crown'], explanation: 'The pound sterling is the world\'s oldest currency still in use, dating back to Anglo-Saxon times. The UK chose not to adopt the euro when it was introduced in 1999, a decision solidified by Brexit in 2020.' },
  { id: 'geo-76', category: 'geography', difficulty: 'medium', question: 'What country is home to the ancient city of Petra?', answer: 'Jordan', options: ['Israel', 'Jordan', 'Syria', 'Lebanon'], explanation: 'Petra was carved into rose-red sandstone cliffs by the Nabataean people over 2,000 years ago. It was named one of the New Seven Wonders of the World in 2007 and is Jordan\'s most-visited tourist attraction.' },
  { id: 'geo-77', category: 'geography', difficulty: 'medium', question: 'What country\'s flag is this: 🇦🇺?', answer: 'Australia', options: ['New Zealand', 'Australia', 'United Kingdom', 'Fiji'], explanation: 'Australia\'s flag features the Union Jack, the Commonwealth Star (seven-pointed), and the Southern Cross constellation. New Zealand\'s flag is similar but has only four red stars with white borders for the Southern Cross.' },
  { id: 'geo-78', category: 'geography', difficulty: 'medium', question: 'What peninsula contains Spain and Portugal?', answer: 'Iberian Peninsula', options: ['Balkan Peninsula', 'Iberian Peninsula', 'Italian Peninsula', 'Scandinavian Peninsula'], explanation: 'The Iberian Peninsula is the second-largest peninsula in Europe, covering about 596,740 square kilometers. It also includes Andorra and Gibraltar, plus a small part of France.' },
  { id: 'geo-79', category: 'geography', difficulty: 'medium', question: 'What is the capital of Morocco?', answer: 'Rabat', options: ['Casablanca', 'Marrakech', 'Rabat', 'Fez'], explanation: 'Rabat has been Morocco\'s capital since 1912 during the French protectorate period. Casablanca is the country\'s largest city and economic hub, while Marrakech and Fez are better-known tourist destinations.' },
  { id: 'geo-80', category: 'geography', difficulty: 'medium', question: 'What is the largest landlocked country in the world?', answer: 'Kazakhstan', options: ['Mongolia', 'Chad', 'Kazakhstan', 'Mali'], explanation: 'Kazakhstan covers about 2.72 million square kilometers in Central Asia, making it the world\'s largest landlocked country and the ninth-largest country overall. It borders Russia, China, Kyrgyzstan, Uzbekistan, and Turkmenistan.' },
  { id: 'geo-81', category: 'geography', difficulty: 'medium', question: 'What famous canal connects the Atlantic and Pacific Oceans?', answer: 'Panama Canal', options: ['Suez Canal', 'Panama Canal', 'Erie Canal', 'Kiel Canal'], explanation: 'The Panama Canal was completed in 1914 by the United States after a failed French attempt. It is about 82 kilometers long and saves ships from having to navigate around the southern tip of South America, reducing the journey by about 15,000 kilometers.' },
  { id: 'geo-82', category: 'geography', difficulty: 'medium', question: 'What country\'s flag is this: 🇬🇷?', answer: 'Greece', options: ['Greece', 'Uruguay', 'Israel', 'Finland'], explanation: 'Greece\'s flag features nine alternating blue and white stripes with a white cross on a blue square in the upper left. The nine stripes are said to represent the nine syllables of the Greek phrase "Freedom or Death."' },
  { id: 'geo-83', category: 'geography', difficulty: 'medium', question: 'What is the most densely populated country in the world?', answer: 'Monaco', options: ['Singapore', 'Monaco', 'Vatican City', 'Malta'], explanation: 'Monaco has about 26,000 people per square kilometer, making it the most densely populated sovereign nation. The city-state covers only 2.02 square kilometers on the French Riviera.' },
  { id: 'geo-84', category: 'geography', difficulty: 'medium', question: 'What river forms much of the border between the United States and Mexico?', answer: 'Rio Grande', options: ['Colorado River', 'Rio Grande', 'Pecos River', 'Brazos River'], explanation: 'The Rio Grande stretches about 3,051 kilometers from Colorado to the Gulf of Mexico. In Mexico, it is called the Rio Bravo del Norte, and it forms the border between Texas and the Mexican states of Chihuahua, Coahuila, Nuevo Leon, and Tamaulipas.' },
  { id: 'geo-85', category: 'geography', difficulty: 'medium', question: 'What is the smallest continent by area?', answer: 'Australia', options: ['Europe', 'Australia', 'Antarctica', 'South America'], explanation: 'Australia covers about 7.7 million square kilometers, making it the smallest continent. It is the only continent that is also a single country, and it is sometimes grouped with the Pacific Islands as "Oceania."' },
  { id: 'geo-86', category: 'geography', difficulty: 'medium', question: 'What Central American country has no army?', answer: 'Costa Rica', options: ['Panama', 'Costa Rica', 'Belize', 'Honduras'], explanation: 'Costa Rica abolished its military in 1948 after a civil war, redirecting military spending to education and healthcare. It is one of the few sovereign nations without a standing army.' },
  { id: 'geo-87', category: 'geography', difficulty: 'medium', question: 'What country is Mount Kilimanjaro located in?', answer: 'Tanzania', options: ['Kenya', 'Tanzania', 'Uganda', 'Ethiopia'], explanation: 'Mount Kilimanjaro stands at 5,895 meters and is Africa\'s highest peak. Though close to the Kenyan border, it is entirely within Tanzania. It is the tallest freestanding mountain in the world.' },
  { id: 'geo-88', category: 'geography', difficulty: 'medium', question: 'What is the national animal of Scotland?', answer: 'Unicorn', options: ['Lion', 'Stag', 'Unicorn', 'Eagle'], explanation: 'Scotland\'s national animal is the unicorn, adopted as a symbol of purity, power, and independence. It has appeared in Scottish heraldry since the 12th century and still features on the Royal Coat of Arms of the United Kingdom.' },
  { id: 'geo-89', category: 'geography', difficulty: 'medium', question: 'What sea is the saltiest in the world?', answer: 'Dead Sea', options: ['Red Sea', 'Caspian Sea', 'Dead Sea', 'Black Sea'], explanation: 'The Dead Sea has a salinity of about 34%, nearly 10 times saltier than the ocean. Its extreme salinity allows people to float effortlessly and prevents almost all aquatic life from surviving in it.' },
  { id: 'geo-90', category: 'geography', difficulty: 'medium', question: 'What country\'s flag is this: 🇨🇭?', answer: 'Switzerland', options: ['Austria', 'Denmark', 'Switzerland', 'Tonga'], explanation: 'Switzerland\'s flag is one of only two square sovereign-state flags in the world (the other is Vatican City). The white cross on a red background inspired the design of the Red Cross symbol, with reversed colors.' },
  { id: 'geo-91', category: 'geography', difficulty: 'hard', question: 'What is the capital of Myanmar?', answer: 'Naypyidaw', options: ['Yangon', 'Mandalay', 'Naypyidaw', 'Bagan'], explanation: 'Naypyidaw replaced Yangon (Rangoon) as Myanmar\'s capital in 2006 when the military government moved the capital to the newly built city. Naypyidaw was built largely in secret and is known for its enormous, mostly empty highways.' },
  { id: 'geo-92', category: 'geography', difficulty: 'hard', question: 'What is the only country in the world that spans all four hemispheres?', answer: 'Kiribati', options: ['Indonesia', 'Kiribati', 'Tuvalu', 'Ecuador'], explanation: 'Kiribati spans the equator (Northern and Southern hemispheres) and the International Date Line (Eastern and Western hemispheres). This small Pacific island nation also became the first country to see the sunrise in the year 2000.' },
  { id: 'geo-93', category: 'geography', difficulty: 'hard', question: 'What is the driest inhabited place on Earth?', answer: 'Atacama Desert, Chile', options: ['Death Valley, USA', 'Sahara Desert, Libya', 'Atacama Desert, Chile', 'Dasht-e Lut, Iran'], explanation: 'Parts of the Atacama Desert in Chile have never recorded rainfall in human history. Despite this extreme aridity, over a million people live in towns and cities within the Atacama, supported by mining and coastal fog water.' },
  { id: 'geo-94', category: 'geography', difficulty: 'hard', question: 'What European microstate is a co-principality ruled by the President of France and a Spanish bishop?', answer: 'Andorra', options: ['Monaco', 'Liechtenstein', 'Andorra', 'San Marino'], explanation: 'Andorra is co-ruled by the President of France and the Bishop of Urgell in Spain. This unique arrangement dates back to 1278, making Andorra the world\'s only co-principality.' },
  { id: 'geo-95', category: 'geography', difficulty: 'hard', question: 'What is the longest mountain range in the world?', answer: 'Andes', options: ['Rocky Mountains', 'Himalayas', 'Andes', 'Great Dividing Range'], explanation: 'The Andes stretch about 7,000 kilometers along the western edge of South America through seven countries. They are the longest continental mountain range, though the Mid-Atlantic Ridge is longer if submarine ranges are counted.' },
  { id: 'geo-96', category: 'geography', difficulty: 'hard', question: 'What is the capital of Sri Lanka?', answer: 'Sri Jayawardenepura Kotte', options: ['Colombo', 'Sri Jayawardenepura Kotte', 'Kandy', 'Galle'], explanation: 'Sri Jayawardenepura Kotte is the official legislative capital, while Colombo serves as the commercial capital and largest city. The parliament was moved to Kotte in 1982, though most government functions still operate from Colombo.' },
  { id: 'geo-97', category: 'geography', difficulty: 'hard', question: 'What country has the most islands?', answer: 'Sweden', options: ['Indonesia', 'Philippines', 'Sweden', 'Finland'], explanation: 'Sweden has approximately 267,570 islands, the most of any country in the world. Most are small, rocky, and uninhabited. Indonesia, while having fewer total islands (around 17,500), has far more large, populated islands.' },
  { id: 'geo-98', category: 'geography', difficulty: 'hard', question: 'What African country was founded by freed American slaves?', answer: 'Liberia', options: ['Sierra Leone', 'Liberia', 'Ghana', 'Senegal'], explanation: 'Liberia was founded in 1822 by the American Colonization Society as a settlement for freed African Americans. Its capital, Monrovia, is named after U.S. President James Monroe, who supported the colonization effort.' },
  { id: 'geo-99', category: 'geography', difficulty: 'hard', question: 'What is the world\'s largest archipelago by number of islands?', answer: 'Malay Archipelago', options: ['Philippine Archipelago', 'Malay Archipelago', 'Japanese Archipelago', 'Indonesian Archipelago'], explanation: 'The Malay Archipelago, located between the Indian and Pacific Oceans, contains over 25,000 islands spanning Indonesia, Malaysia, the Philippines, and neighboring countries. It is the largest island group in the world by area and island count.' },
  { id: 'geo-100', category: 'geography', difficulty: 'hard', question: 'What is the only country whose name in English ends in the letter "H"?', answer: 'Bangladesh', options: ['Bangladesh', 'Kazakhstan', 'Oman', 'Botswana'], explanation: 'Bangladesh is the only internationally recognized sovereign state whose English name ends in "H." The name means "Country of Bengal" in Bengali, with "desh" meaning country or land.' },
  { id: 'geo-101', category: 'geography', difficulty: 'hard', question: 'What is the southernmost capital city in the world?', answer: 'Wellington', options: ['Canberra', 'Buenos Aires', 'Wellington', 'Montevideo'], explanation: 'Wellington, New Zealand sits at about 41 degrees south latitude, making it the southernmost capital of a sovereign state. It is also one of the windiest cities in the world due to its position in the "Roaring Forties" wind belt.' },
  { id: 'geo-102', category: 'geography', difficulty: 'hard', question: 'What landlocked country contains the world\'s largest salt flat?', answer: 'Bolivia', options: ['Argentina', 'Bolivia', 'Chile', 'Peru'], explanation: 'Salar de Uyuni in Bolivia covers about 10,582 square kilometers at an elevation of 3,656 meters. The salt flat contains about 10 billion tonnes of salt and holds a large portion of the world\'s lithium reserves.' },
  { id: 'geo-103', category: 'geography', difficulty: 'hard', question: 'What country is the Socotra archipelago part of?', answer: 'Yemen', options: ['Oman', 'Somalia', 'Yemen', 'Djibouti'], explanation: 'Socotra is a remote island in the Arabian Sea belonging to Yemen, known for its bizarre and alien-looking flora. About a third of its plant species are found nowhere else on Earth, including the iconic dragon blood tree.' },
  { id: 'geo-104', category: 'geography', difficulty: 'hard', question: 'What is the oldest continuously inhabited city in the world?', answer: 'Damascus', options: ['Jerusalem', 'Athens', 'Damascus', 'Varanasi'], explanation: 'Damascus, the capital of Syria, has been continuously inhabited for over 11,000 years. Archaeological evidence dates settlement to around 9000-8000 BC, making it one of the strongest candidates for the oldest continuously lived-in city.' },
  { id: 'geo-105', category: 'geography', difficulty: 'hard', question: 'What country has the most active volcanoes?', answer: 'Indonesia', options: ['Japan', 'United States', 'Indonesia', 'Iceland'], explanation: 'Indonesia has about 130 active volcanoes, the most of any country. The country sits on the Pacific Ring of Fire where several tectonic plates meet. The 1883 eruption of Krakatoa was one of the deadliest volcanic events in recorded history.' },
  { id: 'geo-106', category: 'geography', difficulty: 'hard', question: 'What is the only African country with both Mediterranean and Atlantic coastlines?', answer: 'Morocco', options: ['Tunisia', 'Algeria', 'Morocco', 'Libya'], explanation: 'Morocco has coastline on both the Atlantic Ocean (west) and the Mediterranean Sea (north). The Strait of Gibraltar at Morocco\'s northern tip is only 14 kilometers from Spain.' },
  { id: 'geo-107', category: 'geography', difficulty: 'hard', question: 'What river is the largest by volume of water flow?', answer: 'Amazon', options: ['Congo', 'Ganges', 'Amazon', 'Nile'], explanation: 'The Amazon discharges about 209,000 cubic meters of water per second into the Atlantic Ocean — more than the next seven largest rivers combined. While the Nile is longer, the Amazon carries far more water due to the immense rainfall in its basin.' },
  { id: 'geo-108', category: 'geography', difficulty: 'hard', question: 'What is the capital of Kazakhstan?', answer: 'Astana', options: ['Almaty', 'Astana', 'Nur-Sultan', 'Bishkek'], explanation: 'Astana became Kazakhstan\'s capital in 1997, replacing Almaty. The city was renamed Nur-Sultan in 2019 to honor former president Nursultan Nazarbayev, but was changed back to Astana in 2022.' },
  { id: 'geo-109', category: 'geography', difficulty: 'hard', question: 'What country is home to the world\'s largest cave by volume, Hang Son Doong?', answer: 'Vietnam', options: ['Laos', 'Vietnam', 'Thailand', 'Myanmar'], explanation: 'Hang Son Doong in central Vietnam\'s Phong Nha-Ke Bang National Park is the world\'s largest cave by volume. Discovered by a local man in 1991, it was not explored by scientists until 2009 and contains its own jungle ecosystem inside.' },
  { id: 'geo-110', category: 'geography', difficulty: 'hard', question: 'What island is divided between three countries?', answer: 'Borneo', options: ['Timor', 'Borneo', 'New Guinea', 'Hispaniola'], explanation: 'Borneo is shared by Malaysia (Sabah and Sarawak), Indonesia (Kalimantan), and the small sultanate of Brunei. It is the third-largest island in the world and home to some of Earth\'s oldest rainforests.' },
  { id: 'geo-111', category: 'geography', difficulty: 'hard', question: 'What is the highest capital city in the world?', answer: 'La Paz, Bolivia', options: ['Quito, Ecuador', 'Bogota, Colombia', 'La Paz, Bolivia', 'Addis Ababa, Ethiopia'], explanation: 'La Paz sits at about 3,640 meters (11,942 feet) elevation, making it the highest administrative capital in the world. Bolivia\'s constitutional capital is actually Sucre, but La Paz serves as the seat of government.' },
  { id: 'geo-112', category: 'geography', difficulty: 'hard', question: 'What country\'s flag is this: 🇧🇹?', answer: 'Bhutan', options: ['Nepal', 'Bhutan', 'Sri Lanka', 'Mongolia'], explanation: 'Bhutan\'s flag features a white dragon (the Druk, or Thunder Dragon) on a diagonally divided orange and yellow background. Bhutan calls itself "Druk Yul" meaning "Land of the Thunder Dragon."' },
  { id: 'geo-113', category: 'geography', difficulty: 'hard', question: 'What is the only country in Central America that does not border the Pacific Ocean?', answer: 'Belize', options: ['Honduras', 'Guatemala', 'Belize', 'El Salvador'], explanation: 'Belize sits on the Caribbean coast and borders only Mexico and Guatemala. It is also the only Central American country where English is the official language, having been a British colony (British Honduras) until 1981.' },
  { id: 'geo-114', category: 'geography', difficulty: 'hard', question: 'What is the largest freshwater lake by surface area in the world?', answer: 'Lake Superior', options: ['Lake Victoria', 'Lake Superior', 'Lake Huron', 'Lake Baikal'], explanation: 'Lake Superior covers about 82,100 square kilometers, making it the largest freshwater lake by surface area. The Caspian Sea is larger but is technically a saltwater lake. Lake Baikal holds more water by volume.' },
  { id: 'geo-115', category: 'geography', difficulty: 'hard', question: 'What is the world\'s most remote inhabited island?', answer: 'Tristan da Cunha', options: ['Easter Island', 'Tristan da Cunha', 'Pitcairn Island', 'Bouvet Island'], explanation: 'Tristan da Cunha in the South Atlantic is 2,434 kilometers from the nearest inhabited land (Saint Helena). It has a population of about 250 people and has no airport — the only way to reach it is by a six-day boat journey.' },
  { id: 'geo-116', category: 'geography', difficulty: 'hard', question: 'What country has the most official languages?', answer: 'Zimbabwe', options: ['South Africa', 'India', 'Zimbabwe', 'Bolivia'], explanation: 'Zimbabwe has 16 official languages, including English, Shona, Ndebele, and 13 others recognized in its 2013 constitution. South Africa has 12 official languages, and India recognizes 22 scheduled languages but has no single "official" count at the national level.' },
  { id: 'geo-117', category: 'geography', difficulty: 'hard', question: 'What country contains the geographic South Pole?', answer: 'No country (Antarctica is governed by international treaty)', options: ['Australia', 'No country (Antarctica is governed by international treaty)', 'New Zealand', 'Argentina'], explanation: 'Antarctica is not owned by any country. The Antarctic Treaty of 1959, signed by 12 nations, designated the continent for peaceful scientific research and suspended all territorial claims. The Amundsen-Scott Station sits at the geographic South Pole.' },
  { id: 'geo-118', category: 'geography', difficulty: 'hard', question: 'What country is closest to the intersection of the equator and the Prime Meridian?', answer: 'Ghana', options: ['Gabon', 'Ghana', 'Ecuador', 'Brazil'], explanation: 'The Prime Meridian (0 degrees longitude) passes through the city of Tema in Ghana, and Ghana lies just north of the equator. The actual intersection point of the equator and Prime Meridian (0°N, 0°E) is in the Atlantic Ocean, about 614 km south of Ghana.' },
  { id: 'geo-119', category: 'geography', difficulty: 'hard', question: 'What is the fourth-largest island in the world by area?', answer: 'Madagascar', options: ['Borneo', 'Madagascar', 'Sumatra', 'Greenland'], explanation: 'Madagascar covers about 587,041 square kilometers off the southeastern coast of Africa. It is home to an extraordinary number of unique species — about 90% of its wildlife is found nowhere else on Earth.' },
  { id: 'geo-120', category: 'geography', difficulty: 'hard', question: 'What country\'s flag is this: 🇳🇵?', answer: 'Nepal', options: ['Bhutan', 'Nepal', 'Sri Lanka', 'Bangladesh'], explanation: 'Nepal\'s flag is the only national flag in the world that is not rectangular — it consists of two stacked triangles. The crimson red represents bravery, and the blue borders symbolize peace and harmony.' },
  { id: 'geo-121', category: 'geography', difficulty: 'hard', question: 'What is the largest country in Southeast Asia by area?', answer: 'Indonesia', options: ['Myanmar', 'Thailand', 'Indonesia', 'Vietnam'], explanation: 'Indonesia covers about 1.9 million square kilometers across over 17,000 islands. It is the world\'s largest island country and the fourth most populous nation with over 270 million people.' },
  { id: 'geo-122', category: 'geography', difficulty: 'hard', question: 'What is the only sea without any land boundaries?', answer: 'Sargasso Sea', options: ['Sargasso Sea', 'Coral Sea', 'Philippine Sea', 'Tasman Sea'], explanation: 'The Sargasso Sea in the North Atlantic is bounded entirely by ocean currents rather than land. It is defined by the Gulf Stream, North Atlantic Current, Canary Current, and North Atlantic Equatorial Current. It is named for the Sargassum seaweed that floats on its surface.' },
  { id: 'geo-123', category: 'geography', difficulty: 'hard', question: 'What two countries are doubly landlocked (surrounded entirely by landlocked countries)?', answer: 'Liechtenstein and Uzbekistan', options: ['Liechtenstein and Uzbekistan', 'Switzerland and Mongolia', 'Luxembourg and Nepal', 'Andorra and Laos'], explanation: 'Liechtenstein (bordered by Austria and Switzerland) and Uzbekistan (bordered by Afghanistan, Kazakhstan, Kyrgyzstan, Tajikistan, and Turkmenistan) are the only two doubly landlocked countries. You must cross at least two borders to reach the sea from either one.' },
  { id: 'geo-124', category: 'geography', difficulty: 'hard', question: 'What is the largest tidal range in the world found at?', answer: 'Bay of Fundy, Canada', options: ['Mont Saint-Michel, France', 'Bay of Fundy, Canada', 'Bristol Channel, UK', 'Cook Inlet, Alaska'], explanation: 'The Bay of Fundy between New Brunswick and Nova Scotia experiences tidal ranges of up to 16 meters (53 feet). Approximately 160 billion tonnes of water flow in and out of the bay with each tide cycle.' },
  { id: 'geo-125', category: 'geography', difficulty: 'hard', question: 'What country was formerly known as Siam?', answer: 'Thailand', options: ['Myanmar', 'Cambodia', 'Thailand', 'Laos'], explanation: 'Thailand was known as Siam until 1939, when Prime Minister Plaek Phibunsongkhram changed the name. The word "Thai" means "free," making Thailand the "Land of the Free." It briefly reverted to Siam from 1945-1949 before becoming Thailand again.' },
]
